    answer[0] = 1
    for i in range(limit + 1):
        if answer[i] == 1:
            if i + numberA <= limit:
                answer[i + numberA] = 1
            if i + numberB <= limit:
                answer[i + numberB] = 1
    return sum(answer[1:])

